const repoUrl = $vars.repoUrl || 'https://api.github.com/repos/owner/repo';
const githubToken = $vars.githubToken || '';
const claudeApiKey = $vars.claudeApiKey || '';
const webhookUrl = $vars.webhookUrl || '';
const language = ($vars.language || 'EN').toUpperCase();
const since = new Date(Date.now() - 7 * 24 * 60 * 60 * 1000).toISOString().split('T')[0];

return [{ repoUrl, githubToken, claudeApiKey, webhookUrl, language, since }];

const items = $input.all();
const config = items[0].json;

const commits = (items[1]?.json || []);
const commitList = Array.isArray(commits) ? commits : (commits._node === 'Fetch Commits' ? items.slice(1).map(i => i.json) : []);
const issues = items[2]?.json || [];
const prs = items[3]?.json || [];

const commitMsgs = (Array.isArray(commits) ? commits : [])
  .slice(0, 30)
  .map(c => `- ${(c.commit?.message || '').split('\n')[0]} (${c.commit?.author?.name || 'unknown'})`)
  .join('\n');

const issueList = (Array.isArray(issues) ? issues : [])
  .filter(i => !i.pull_request)
  .slice(0, 20)
  .map(i => `- #${i.number} ${i.title}`)
  .join('\n');

const prList = (Array.isArray(prs) ? prs : [])
  .filter(p => p.merged_at && new Date(p.merged_at) > new Date(Date.now() - 8*24*60*60*1000))
  .slice(0, 20)
  .map(p => `- #${p.number} ${p.title} (${p.user?.login || 'unknown'})`)
  .join('\n');

const lang = config.language === 'FR' ? 'French' : 'English';

const prompt = `Write a weekly development summary in ${lang} for the repository ${config.repoUrl}.

## Activity This Week

### Commits (${Array.isArray(commits) ? commits.length : 0})
${commitMsgs || 'None'}

### Closed Issues (${Array.isArray(issues) ? issues.filter(i => !i.pull_request).length : 0})
${issueList || 'None'}

### Merged PRs (${Array.isArray(prs) ? prs.filter(p => p.merged_at).length : 0})
${prList || 'None'}

Write a concise narrative (under 300 words) covering:
1. Key highlights and major changes
2. Bug fixes and improvements
3. Notable patterns or trends
4. Overall project health

Use a professional but friendly tone.`;

return [{
  repoUrl: config.repoUrl,
  claudeApiKey: config.claudeApiKey,
  webhookUrl: config.webhookUrl,
  prompt
}];

